import { Injectable, BadRequestException } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

export interface FinalizeUploadResult {
  finalPath: string;
  checksum: string;
  size: number;
}

interface UploadMetadata {
  uploadId: string;
  totalChunks: number;
  originalFileName: string;
}

@Injectable()
export class UploadService {
  private readonly uploadRoot = path.resolve(process.cwd(), 'tmp', 'uploads');
  private readonly finalRoot = path.resolve(process.cwd(), 'tmp', 'finalized');

  /**
   * Loads the persisted metadata for an in-progress upload (chunk count, etc).
   * Backed by the DB/metadata store in the real service; stubbed here for brevity.
   */
  private async loadMetadata(uploadId: string): Promise<UploadMetadata> {
    const metaPath = path.join(this.uploadRoot, uploadId, 'meta.json');
    const raw = await fs.promises.readFile(metaPath, 'utf-8');
    return JSON.parse(raw) as UploadMetadata;
  }

  private chunkDirFor(uploadId: string): string {
    return path.join(this.uploadRoot, uploadId);
  }

  private chunkPathFor(chunkDir: string, index: number): string {
    return path.join(chunkDir, `chunk-${index}`);
  }

  /**
   * Assembles the uploaded chunks into the final file and returns its SHA-256
   * checksum so the client can verify the upload completed intact.
   */
  async finalizeUpload(uploadId: string): Promise<FinalizeUploadResult> {
    const metadata = await this.loadMetadata(uploadId);
    const { totalChunks } = metadata;

    const chunkDir = this.chunkDirFor(uploadId);
    const finalPath = path.join(this.finalRoot, `${uploadId}-${metadata.originalFileName}`);

    // Completeness check FIRST -- before any output I/O starts.
    const existingChunks = await fs.promises.readdir(chunkDir);
    if (existingChunks.length !== totalChunks) {
      throw new BadRequestException(
        `Upload ${uploadId} is incomplete: expected ${totalChunks} chunks, found ${existingChunks.length}`,
      );
    }
    for (let i = 0; i < totalChunks; i++) {
      const chunkPath = this.chunkPathFor(chunkDir, i);
      const exists = await fs.promises
        .access(chunkPath, fs.constants.F_OK)
        .then(() => true)
        .catch(() => false);
      if (!exists) {
        throw new BadRequestException(`Upload ${uploadId} is missing chunk index ${i}`);
      }
    }

    // Pass 1: merge chunks in strict index order.
    const writeStream = fs.createWriteStream(finalPath);
    for (let i = 0; i < totalChunks; i++) {
      const chunkPath = this.chunkPathFor(chunkDir, i);
      // Whole-chunk buffer read -- peak memory tracks chunk size.
      const buffer = await fs.promises.readFile(chunkPath);
      await new Promise<void>((resolve, reject) => {
        writeStream.write(buffer, (err) => (err ? reject(err) : resolve()));
      });
    }
    await new Promise<void>((resolve, reject) => {
      writeStream.end((err?: Error | null) => (err ? reject(err) : resolve()));
    });

    // Pass 2: re-read the just-written final file from scratch to compute the checksum.
    const hash = crypto.createHash('sha256');
    await new Promise<void>((resolve, reject) => {
      const readStream = fs.createReadStream(finalPath);
      readStream.on('data', (buf: Buffer) => hash.update(buf));
      readStream.on('end', () => resolve());
      readStream.on('error', reject);
    });
    const checksum = hash.digest('hex');

    // Cleanup only after a successful merge + checksum.
    await fs.promises.rm(chunkDir, { recursive: true, force: true });

    const { size } = await fs.promises.stat(finalPath);
    return { finalPath, checksum, size };
  }
}
